<script setup lang="ts">
import { ref } from 'vue'
const props=defineProps<{modelValue:Record<string,any>,specs:any[],groups:string[],buildMode:string}>()
const emit=defineEmits<{ 'update:modelValue':[value:Record<string,any>],validity:[value:{path:string,message:string}] }>()
const raw=ref<Record<string,string>>({}),errors=ref<Record<string,string>>({})
function compatible(spec:any,value:any){
 if(value===null||value===undefined)return true
 if(spec.kind==='lines')return Array.isArray(value)&&value.every(x=>typeof x==='string')
 if(spec.kind==='records')return Array.isArray(value)&&value.every(x=>x&&typeof x==='object'&&!Array.isArray(x))
 if(spec.kind==='mapping')return typeof value==='object'&&!Array.isArray(value)
 if(spec.kind==='boolean')return typeof value==='boolean'
 if(spec.kind==='integer'||spec.kind==='number')return typeof value==='number'&&Number.isFinite(value)
 return typeof value==='string'
}
function change(spec:any,value:any){emit('update:modelValue',{...props.modelValue,[spec.path]:value});errors.value[spec.path]='';emit('validity',{path:spec.path,message:''})}
function complex(spec:any,text:string){raw.value[spec.path]=text;try{const value=JSON.parse(text);if(spec.kind==='records'?(!Array.isArray(value)||value.some((x:any)=>!x||typeof x!=='object'||Array.isArray(x))):(!value||typeof value!=='object'||Array.isArray(value)))throw Error();change(spec,value)}catch{errors.value[spec.path]='格式未完成：请填写'+(spec.kind==='records'?'对象数组，例如 [{"caller":"A","callee":"B"}]':'对象，例如 {"linked_sources":[]}');emit('validity',{path:spec.path,message:errors.value[spec.path]})}}
</script>
<template><section class="profile-options" aria-label="逐项附加配置"><p class="muted">未设置的项沿用引擎默认。点击“设置”才写入配置；“恢复默认”移除此项。每行参数会原样保留空格。</p><template v-for="group in groups" :key="group"><h3>{{group}}</h3><details v-for="spec in specs.filter(s=>s.group===group&&(buildMode==='cmake'||!s.path.startsWith('analysis.cmake.')))" :key="spec.path" class="option-card"><summary>{{spec.label}} <span>{{modelValue[spec.path]===null||modelValue[spec.path]===undefined?'未设置':spec.kind==='boolean'?(modelValue[spec.path]?'开启':'关闭'):'已配置'}}</span></summary><p class="option-hint" :id="'hint-'+spec.path">{{spec.hint}}</p><small>{{spec.path}}</small><div class="actions"><button v-if="modelValue[spec.path]===null||modelValue[spec.path]===undefined" type="button" @click="change(spec,spec.kind==='boolean'?false:spec.kind==='lines'||spec.kind==='records'?[]:spec.kind==='mapping'?{}:spec.kind==='integer'||spec.kind==='number'?Number(spec.example||1):spec.example||'')">设置{{spec.label}}</button><button v-else type="button" @click="change(spec,null);delete raw[spec.path]">恢复默认</button></div><p v-if="!compatible(spec,modelValue[spec.path])" role="alert" class="banner error">当前原文的值格式不正确。请点“恢复默认”后重新设置，或在高级YAML修复；原文尚未改写。</p><template v-if="modelValue[spec.path]!==null&&modelValue[spec.path]!==undefined&&compatible(spec,modelValue[spec.path])"><label>{{spec.label}}<select v-if="spec.kind==='boolean'" :aria-label="spec.label" :aria-describedby="'hint-'+spec.path" :value="String(modelValue[spec.path])" @change="change(spec,($event.target as HTMLSelectElement).value==='true')"><option value="false">关闭</option><option value="true">开启</option></select><textarea v-else-if="spec.kind==='lines'" :aria-label="spec.label" :aria-describedby="'hint-'+spec.path" rows="3" :placeholder="spec.example" :value="modelValue[spec.path].join('\n')" @input="change(spec,($event.target as HTMLTextAreaElement).value.split(/\r?\n/).filter(x=>x.length>0))"/><textarea v-else-if="['records','mapping'].includes(spec.kind)" :aria-label="spec.label" :aria-describedby="'hint-'+spec.path" rows="6" spellcheck="false" :value="raw[spec.path]??JSON.stringify(modelValue[spec.path],null,2)" @input="complex(spec,($event.target as HTMLTextAreaElement).value)"/><input v-else :aria-label="spec.label" :aria-describedby="'hint-'+spec.path" :type="['integer','number'].includes(spec.kind)?'number':'text'" :min="spec.minimum??undefined" :max="spec.maximum??undefined" :step="spec.kind==='integer'?1:'any'" :value="modelValue[spec.path]" :placeholder="spec.example" @input="change(spec,['integer','number'].includes(spec.kind)?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value)"></label><p v-if="['records','mapping'].includes(spec.kind)" class="muted">此扩展段用JSON编辑（与YAML等价）；只改本段，其余原文保留。格式示例：<pre>{{spec.example}}</pre></p></template><p v-if="errors[spec.path]" role="alert" class="banner error">{{errors[spec.path]}}</p></details></template></section></template>
<style scoped>.profile-options{margin-top:12px}.option-card{border-bottom:1px solid #d9e1ed;padding:8px 0}.option-card summary{font-weight:600;cursor:pointer}.option-card summary span{float:right;color:#64748b;font-size:12px;font-weight:400}.option-card small{display:block;color:#64748b;margin-bottom:6px}.option-hint{margin:8px 0;font-size:13px}.option-card textarea{font-size:14px}.option-card pre{white-space:pre-wrap;font-size:12px}</style>
